// =============================================================================
// SEASONALITY DETECTION PARITY
// =============================================================================

#[test]
fn seasonality_periodic_data() {
    // Clear 7-period seasonality
    let values: Vec<f64> = (0..56)
        .map(|i| {
            let trend = i as f64 * 0.5;
            let seasonal = 10.0 * (2.0 * std::f64::consts::PI * i as f64 / 7.0).sin();
            trend + seasonal + 50.0
        })
        .collect();
    let series = make_series(values);
    let results = detect_seasonality(&series.values).unwrap();

    println!("=== SEASONALITY DETECTION ===");
    for r in &results {
        println!("period={}, strength={:.4}", r.period, r.strength);
    }

    // Should detect period=7
    assert!(
        results.iter().any(|r| r.period == 7),
        "Should detect period 7, got: {:?}",
        results.iter().map(|r| r.period).collect::<Vec<_>>()
    );
}

// =============================================================================
// CROSS-MODEL CONSISTENCY
// =============================================================================

#[test]
fn all_models_produce_valid_output() {
    let values: Vec<f64> = (0..20)
        .map(|i| 100.0 + 5.0 * i as f64 + (i as f64 * 0.8).sin() * 3.0)
        .collect();
    let series = make_series(values);

    let models = vec![
        ("linear", ForecastModel::Linear),
        ("exponential", ForecastModel::Exponential),
        ("ets", ForecastModel::ETS),
        ("auto", ForecastModel::Auto),
    ];

    println!("=== ALL MODELS COMPARISON ===");
    for (name, model) in &models {
        let config = ForecastConfig {
            model: model.clone(),
            horizon: 5,
            confidence_level: 0.95,
        };
        let result = forecast(&series, &config).unwrap();

        println!("\n--- {} ---", name);
        for i in 0..5 {
            let width = result.upper_bounds[i] - result.lower_bounds[i];
            println!(
                "  step {}: forecast={:.2}, lower={:.2}, upper={:.2}, width={:.2}",
                i + 1, result.forecasts[i], result.lower_bounds[i], result.upper_bounds[i], width
            );
        }

        // Basic validity checks for all models
        assert_eq!(result.forecasts.len(), 5, "{} should produce 5 forecasts", name);
        assert_eq!(result.timestamps.len(), 5, "{} should produce 5 timestamps", name);
        for i in 0..5 {
            assert!(
                result.upper_bounds[i] >= result.lower_bounds[i],
                "{} step {}: upper {:.4} should be >= lower {:.4}",
                name, i + 1, result.upper_bounds[i], result.lower_bounds[i]
            );
            assert!(
                result.forecasts[i] >= result.lower_bounds[i],
                "{} step {}: forecast {:.4} should be >= lower {:.4}",
                name, i + 1, result.forecasts[i], result.lower_bounds[i]
            );
            assert!(
                result.forecasts[i] <= result.upper_bounds[i],
                "{} step {}: forecast {:.4} should be <= upper {:.4}",
                name, i + 1, result.forecasts[i], result.upper_bounds[i]
            );
            assert!(!result.forecasts[i].is_nan(), "{} forecast[{}] is NaN", name, i);
            assert!(!result.lower_bounds[i].is_nan(), "{} lower[{}] is NaN", name, i);
            assert!(!result.upper_bounds[i].is_nan(), "{} upper[{}] is NaN", name, i);
        }
    }
}

#[test]
fn bands_widen_all_models() {
    // Noisy data — bands should widen for all models that support prediction intervals
    let values = vec![
        22.1, 19.8, 24.5, 21.0, 26.3, 20.7, 23.9, 18.2,
        25.6, 22.4, 27.1, 19.5, 24.8, 21.3, 26.7, 20.1,
        23.4, 25.9, 18.7, 24.2,
    ];
    let series = make_series(values);

    println!("=== BAND WIDENING CHECK ===");

    // Linear should definitely widen
    let result = linear::forecast_linear(&series, 10, 0.95).unwrap();
    let widths: Vec<f64> = (0..10)
        .map(|i| result.upper_bounds[i] - result.lower_bounds[i])
        .collect();

    println!("Linear band widths: {:?}", widths.iter().map(|w| format!("{:.2}", w)).collect::<Vec<_>>());

    for w in widths.windows(2) {
        assert!(
            w[1] > w[0],
            "Linear bands must widen: {:.4} -> {:.4}",
            w[0], w[1]
        );
    }

    // Exponential should also widen
    // Need all positive values (already are)
    let result = exponential::forecast_exponential(&series, 10, 0.95).unwrap();
    let widths: Vec<f64> = (0..10)
        .map(|i| result.upper_bounds[i] - result.lower_bounds[i])
        .collect();

    println!("Exponential band widths: {:?}", widths.iter().map(|w| format!("{:.2}", w)).collect::<Vec<_>>());

    for w in widths.windows(2) {
        assert!(
            w[1] > w[0],
            "Exponential bands must widen: {:.4} -> {:.4}",
            w[0], w[1]
        );
    }
}

#[test]
fn timestamps_are_sequential() {
    let values: Vec<f64> = (0..15).map(|i| 100.0 + i as f64 * 3.0).collect();
    let series = make_series(values);
    let result = linear::forecast_linear(&series, 5, 0.95).unwrap();

    // Timestamps should continue from the last one
    let last_ts = 1000 + 14; // timestamps start at 1000, 15 values = last is 1014
    for i in 0..5 {
        assert_eq!(
            result.timestamps[i],
            last_ts + (i as i32 + 1),
            "Timestamp {} should be {}",
            i, last_ts + (i as i32 + 1)
        );
    }
}
